{{(() => {
  const ratings = [
    Rating18Copy.value,
		Rating19Copy.value,
		Rating20Copy.value,
		Rating21Copy.value,
		Rating22Copy.value,
    Rating23Copy.value,
		Rating24Copy.value,
		Rating25Copy.value,
		Rating26Copy.value,
		Rating27Copy.value,
    Rating28Copy.value
  ];

  const hasInvalidRating = ratings.some(r => r === null || r === 0);

  if (hasInvalidRating) {
    return "OBIETTIVO DELLA SETTIMANA: RISPETTO DELL'ORDINE ORGANIZZATIVO E VOLONTÀ DI APPRENDERE";
  }

  const somma = ratings.reduce((acc, val) => acc + val, 0);

  return somma === 0 ? "" : (somma === 33 ? "OBIETTIVO DELLA SETTIMANA RAGGIUNTO: RISPETTO DELL'ORDINE ORGANIZZATIVO E VOLONTÀ DI APPRENDERE" : "OBIETTIVO DELLA SETTIMANA NON RAGGIUNTO: RISPETTO DELL'ORDINE ORGANIZZATIVO E VOLONTÀ DI APPRENDERE");
})()
}}

